-- 112: duas ofertas no pico. Quem já é aluno tem oferta própria, separada da principal.
update pico_template_tarefas set titulo = 'Definir a oferta para quem já é aluno', criterio_pronto = 'Produto, preço e desconto da oferta de aluno, com a regra de quem conta como aluno', campos = '[{"chave": "produto_aluno", "label": "Produto para alunos", "tipo": "texto", "vinculo": "produto_aluno", "dica": "O que quem já é aluno compra na Black. Assinatura não vira vitalício"}, {"chave": "preco_normal_aluno", "label": "Preço fora do pico", "tipo": "moeda", "vinculo": "preco_normal_aluno", "base": true}, {"chave": "preco_aluno", "label": "Preço no pico para alunos", "tipo": "moeda", "vinculo": "preco_aluno", "base_de": "preco_normal_aluno", "par_percent": "desconto_aluno"}, {"chave": "desconto_aluno", "label": "Desconto", "tipo": "percent", "vinculo": "desconto_aluno_pct", "base_de": "preco_normal_aluno", "par_valor": "preco_aluno"}, {"chave": "regra", "label": "Quem conta como aluno e como a oferta chega nele", "tipo": "texto_longo", "vinculo": "regra_credito"}]'::jsonb where titulo = 'Definir a regra de crédito para quem já comprou';
update pico_template_tarefas set campos = '[{"chave": "produto", "label": "Produto da oferta principal (não alunos)", "tipo": "texto", "vinculo": "produto", "dica": "O que exatamente vai ser vendido para quem ainda não é aluno"}, {"chave": "preco_normal", "label": "Preço fora do pico", "tipo": "moeda", "vinculo": "preco_normal", "base": true}, {"chave": "modo", "label": "Definir o preço do pico por", "tipo": "opcao", "opcoes": ["Valor", "Desconto"], "dica": "Escolha por onde é mais natural pensar. O outro campo se calcula sozinho"}, {"chave": "preco_pico", "label": "Preço no pico", "tipo": "moeda", "vinculo": "preco_pico", "base_de": "preco_normal", "alimenta": "projeto.ticket", "so_quando": {"modo": "Valor"}, "par_percent": "desconto_pct"}, {"chave": "desconto_pct", "label": "Desconto", "tipo": "percent", "vinculo": "desconto_pct", "base_de": "preco_normal", "par_valor": "preco_pico", "so_quando": {"modo": "Desconto"}}, {"chave": "resumo", "label": "Fica assim", "tipo": "resumo_preco"}]'::jsonb where titulo = 'Definir produto principal, preço fora do pico e preço do pico';
update pico_tarefas set titulo = 'Definir a oferta para quem já é aluno', criterio_pronto = 'Produto, preço e desconto da oferta de aluno, com a regra de quem conta como aluno', campos = '[{"chave": "produto_aluno", "label": "Produto para alunos", "tipo": "texto", "vinculo": "produto_aluno", "dica": "O que quem já é aluno compra na Black. Assinatura não vira vitalício"}, {"chave": "preco_normal_aluno", "label": "Preço fora do pico", "tipo": "moeda", "vinculo": "preco_normal_aluno", "base": true}, {"chave": "preco_aluno", "label": "Preço no pico para alunos", "tipo": "moeda", "vinculo": "preco_aluno", "base_de": "preco_normal_aluno", "par_percent": "desconto_aluno"}, {"chave": "desconto_aluno", "label": "Desconto", "tipo": "percent", "vinculo": "desconto_aluno_pct", "base_de": "preco_normal_aluno", "par_valor": "preco_aluno"}, {"chave": "regra", "label": "Quem conta como aluno e como a oferta chega nele", "tipo": "texto_longo", "vinculo": "regra_credito"}]'::jsonb where titulo = 'Definir a regra de crédito para quem já comprou';
update pico_tarefas set campos = '[{"chave": "produto", "label": "Produto da oferta principal (não alunos)", "tipo": "texto", "vinculo": "produto", "dica": "O que exatamente vai ser vendido para quem ainda não é aluno"}, {"chave": "preco_normal", "label": "Preço fora do pico", "tipo": "moeda", "vinculo": "preco_normal", "base": true}, {"chave": "modo", "label": "Definir o preço do pico por", "tipo": "opcao", "opcoes": ["Valor", "Desconto"], "dica": "Escolha por onde é mais natural pensar. O outro campo se calcula sozinho"}, {"chave": "preco_pico", "label": "Preço no pico", "tipo": "moeda", "vinculo": "preco_pico", "base_de": "preco_normal", "alimenta": "projeto.ticket", "so_quando": {"modo": "Valor"}, "par_percent": "desconto_pct"}, {"chave": "desconto_pct", "label": "Desconto", "tipo": "percent", "vinculo": "desconto_pct", "base_de": "preco_normal", "par_valor": "preco_pico", "so_quando": {"modo": "Desconto"}}, {"chave": "resumo", "label": "Fica assim", "tipo": "resumo_preco"}]'::jsonb where titulo = 'Definir produto principal, preço fora do pico e preço do pico';
